def minTimeThroughGates(grid):
    rows, cols = len(grid), len(grid[0])
    goal = rows * cols - 1
    if goal == 0:
        return 0
    seen = [[False, False] for _ in range(rows * cols)]
    seen[0][0] = True
    frontier = [0]
    t = 0
    while frontier:
        t += 1
        par = t & 1
        nxt = []
        for u in frontier:
            r, c = divmod(u, cols)
            for nr, nc in ((r, c), (r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < rows and 0 <= nc < cols:
                    v = grid[nr][nc]
                    if v == 0 or (v == 2 and par == 0) or (v == 3 and par == 1):
                        w = nr * cols + nc
                        if not seen[w][par]:
                            seen[w][par] = True
                            if w == goal:
                                return t
                            nxt.append(w)
        frontier = nxt
    return -1
